import { Component, OnInit } from '@angular/core';
import { SharedIonic } from '../../../../../core/common/SharedIonic';
import { GResponse } from '../../../../../core/common/GResponse';
import { ICourseModel } from '../../../../../data/model/course/CourseModel';
import { CourseFilterModel, ICourseFilterModel } from '../../../../../data/model/course/CourseFilterModel';
import { FormBuilder, FormGroup, Validators } from '@angular/forms';
import { ActivatedRoute, Router } from '@angular/router';
import { AlertController, LoadingController, ToastController } from '@ionic/angular';
import { CourseService } from '../../../../../data/service/course/course.service';
import { CourseDetailModel, ICourseDetailModel } from '../../../../../data/model/course/CourseDetailModel';
import { AddOrUpdateCourseImageModel, CourseImageModel } from '../../../../../data/model/course/CourseVideoModel';

@Component({
  selector: 'app-add-image',
  templateUrl: './add-image.component.html',
  styleUrls: ['./add-image.component.scss']
})
export class AddImageComponent implements OnInit {

  segmentSelected = 'Add';
  searchTitle = '';
  selectedCourseId = 0;
  courseSelected = false;
  courseDetail: ICourseDetailModel;
  course: ICourseModel;
  filteredCourses: ICourseFilterModel;
  updateForm: FormGroup;
  addForm: FormGroup;
  selectedImageIndex = -1;
  empty = false;

  constructor(
    private courseService: CourseService,
    private fb: FormBuilder,
    public toastController: ToastController,
    public loadingController: LoadingController,
    private activatedRoute: ActivatedRoute,
    public alertController: AlertController,
    private router: Router) { }

  ngOnInit(): void {

    this.updateForm = this.fb.group({
      name: ['', [Validators.required, Validators.minLength(5), Validators.maxLength(1000000)]],
      url: ['', [Validators.required, Validators.minLength(5), Validators.maxLength(1000000)]]
    });

    this.addForm = this.fb.group({
      name: ['', [Validators.required, Validators.minLength(5), Validators.maxLength(1000000)]],
      url: ['', [Validators.required, Validators.minLength(5), Validators.maxLength(1000000)]]
    });

    let filter: ICourseFilterModel;

    this.activatedRoute.queryParams.subscribe(params => {

      const page = params.page;
      const take = params.take ? params.take : 12;
      const title = params.title ? params.title : null;
      const startPrice = params.startPrice ? params.startPrice : null;
      const endPrice = params.endPrice ? params.endPrice : null;
      const categoryIds = params.categoryIds ? params.categoryIds : [];
      const sortId = params.sortId ? params.sortId : 4;

      if (page === undefined) {
        filter =
        filter = new CourseFilterModel(false, page, take, title);
      } else {
        if (
          startPrice == null &&
          endPrice == null &&
          categoryIds == null &&
          sortId == null) {

          filter = new CourseFilterModel(false, page, take, title);
        } else {
          filter =
            new CourseFilterModel(true, page, take, title, startPrice, endPrice, categoryIds, sortId);
        }
      }
      this.filteredCourses = filter;

      SharedIonic.loading(this.loadingController);

      this.courseService.GetTeacherCoursesByFilter(filter).subscribe(
        res => {
          SharedIonic.dismissLoading(this.loadingController);
          if (res.status === GResponse.SuccessStatus) {
            this.filteredCourses = res.data;
          } else {
            this.empty = true;
          }
        },
        err => {
          SharedIonic.dismissLoading(this.loadingController);
          SharedIonic.unSuccessToast(this.toastController);
        }
      );
    });
  }

  onSelectVideo(index: number | string): void {

    this.selectedImageIndex = +index;

    this.updateForm.setValue({
      name: this.courseDetail.courseImages[+index].title,
      url: this.courseDetail.courseImages[+index].url
    });
  }

  async presentAlertConfirm(index) {
    const alert = await this.alertController.create({
      cssClass: 'main-alert',
      header: 'هشدار!',
      message: 'آیا مطمئن به حذف هستید؟!؟',
      buttons: [
        {
          text: 'لغو',
          role: 'cancel',
          cssClass: 'secondary',
          handler: () => {
          }
        }, {
          text: 'حذف',
          handler: () => {
            this.onDelete(index);
          }
        }
      ]
    });

    await alert.present();
  }

  async presentAlertConfirm2() {
    const alert = await this.alertController.create({
      cssClass: 'main-alert',
      header: 'هشدار!',
      message: 'آیا مطمئن هستید؟',
      buttons: [
        {
          text: 'لغو',
          role: 'cancel',
          cssClass: 'secondary',
          handler: () => {
          }
        }, {
          text: 'بله',
          handler: () => {
            this.onUpdate();
          }
        }
      ]
    });

    await alert.present();
  }

  async presentAlertConfirm3() {
    const alert = await this.alertController.create({
      cssClass: 'main-alert',
      header: 'هشدار!',
      message: 'آیا مطمئن هستید؟',
      buttons: [
        {
          text: 'لغو',
          role: 'cancel',
          cssClass: 'secondary',
          handler: () => {
          }
        }, {
          text: 'بله',
          handler: () => {
            this.onAdd();
          }
        }
      ]
    });

    await alert.present();
  }

  onDelete(index: number | string): void {

    this.selectedImageIndex = +index;

    SharedIonic.loading(this.loadingController);

    this.courseService.DeleteImage(this.courseDetail.courseImages[this.selectedImageIndex].id).subscribe(
      res => {
        SharedIonic.dismissLoading(this.loadingController);
        if (GResponse.SuccessStatus === res.status) {

          this.courseDetail.courseImages.splice(this.selectedImageIndex, 1);

          this.updateForm.setValue({
            name: '',
            url: ''
          });
          // this.selectedCourseId = 0;
          // this.courseSelected = false;
          // this.setQueryParams(1);
          SharedIonic.successToast(this.toastController);
        } else {
          SharedIonic.unSuccessToast(this.toastController);
        }
      },
      err => {
        SharedIonic.dismissLoading(this.loadingController);
        SharedIonic.unSuccessToast(this.toastController);
      }
    );
  }

  onUpdate() {

    if (this.updateForm.valid || this.selectedImageIndex != -1) {

      SharedIonic.loading(this.loadingController);

      this.courseService.AddOrUpdateImage(
        new AddOrUpdateCourseImageModel(
          this.courseDetail.id,
          new CourseImageModel(
            this.courseDetail.courseImages[this.selectedImageIndex].id,
            false,
            this.updateForm.value.name,
            this.updateForm.value.url
          )
        )
      ).subscribe(
        res => {
          SharedIonic.dismissLoading(this.loadingController);
          if (GResponse.SuccessStatus === res.status) {

            this.courseDetail.courseImages[this.selectedImageIndex].title = this.updateForm.value.name;
            this.courseDetail.courseImages[this.selectedImageIndex].url = this.updateForm.value.url;

            this.updateForm.setValue({
              name: '',
              url: ''
            });
            this.selectedImageIndex = -1;
            // this.onSelectItem(this.course);
            SharedIonic.successToast(this.toastController);
          } else {
            SharedIonic.unSuccessToast(this.toastController);
          }
        },
        err => {
          SharedIonic.dismissLoading(this.loadingController);
          SharedIonic.unSuccessToast(this.toastController);
        }
      );
    }
  }

  onAdd() {

    if (this.addForm.valid) {

      SharedIonic.loading(this.loadingController);

      this.courseService.AddOrUpdateImage(
        new AddOrUpdateCourseImageModel(
          this.courseDetail.id,
          new CourseImageModel(
            0,
            false,
            this.addForm.value.name,
            this.addForm.value.url
          )
        )
      ).subscribe(
        res => {
          SharedIonic.dismissLoading(this.loadingController);
          if (GResponse.SuccessStatus === res.status) {
            this.addForm.setValue({
              name: '',
              url: ''
            });
            this.onSelectItem(this.course);
            SharedIonic.successToast(this.toastController);
          } else {
            SharedIonic.unSuccessToast(this.toastController);
          }
        },
        err => {
          SharedIonic.dismissLoading(this.loadingController);
          SharedIonic.unSuccessToast(this.toastController);
        }
      );
    }
  }

  MakePageCountArray(pageCount: number | string): Array<number | string> {

    const array: string[] = [];

    for (let i = 1; i <= pageCount; i++) {

      array.push(i.toString());
    }

    return array;
  }

  goPreviousPage() {

    if (this.filteredCourses.startPage == null) {
      return;
    }
    if (this.filteredCourses.pageId > this.filteredCourses.startPage && +this.filteredCourses.pageId - 1 > 0) {
      this.setQueryParams(+this.filteredCourses.pageId - 1);
    }
  }

  goNextPage() {

    if (this.filteredCourses.endPage == null) {
      return;
    }
    if (this.filteredCourses.pageId < this.filteredCourses.endPage) {
      this.setQueryParams(+this.filteredCourses.pageId + 1);
    }
  }

  goPage(pageId: number | string) {
    this.setQueryParams(+pageId);
  }

  setQueryParams(pageId: number) {

    this.filteredCourses.title = this.searchTitle;

    this.router
      .navigate(
        ['TeacherPanel', 'AddImage'],
        {
          queryParams:
          {
            page: pageId < 1 ? 1 : pageId,
            take: this.filteredCourses.takeEntity ? this.filteredCourses.takeEntity : null,
            title: this.filteredCourses.title ? this.filteredCourses.title : null,
            startPrice: this.filteredCourses.startPrice ? this.filteredCourses.startPrice : null,
            endPrice: this.filteredCourses.endPrice ? this.filteredCourses.endPrice : null,
            categoryIds: this.filteredCourses.categoryIds ? this.filteredCourses.categoryIds : [],
            sortId: this.filteredCourses.sortId ? this.filteredCourses.sortId : 0
          }
        });
  }

  onSelectItem(model: ICourseModel) {

    this.selectedCourseId = +model.id;
    this.course = model;

    // tslint:disable-next-line: max-line-length
    this.courseDetail = new CourseDetailModel(this.selectedCourseId, model.name, model.price, model.offPrice, 0, model.shortDescription, model.description, model.imageUrl, '', '', model.createDate, model.lastUpdateDate, [], [], [], false, model.teacher, false, model.isActive, '', '', '', 100);

    SharedIonic.loading(this.loadingController);

    this.courseService.GetTeacherCourseDetailImagesById(this.selectedCourseId).subscribe(
      res => {
        SharedIonic.dismissLoading(this.loadingController);
        if (GResponse.SuccessStatus === res.status) {

          const photos = [];

          res.data.forEach(v => {
            photos.push(
              // tslint:disable-next-line: max-line-length
              new CourseImageModel(v.id, v.isActive, v.title, v.url)
            );
          });
          this.courseDetail.courseImages = photos;
          this.updateForm.setValue({
            name: '',
            url: ''
          });
          this.courseSelected = true;
        } else {
          this.courseDetail.courseImages = [];
          SharedIonic.unSuccessToast(this.toastController);
          this.selectedCourseId = 0;
          this.courseSelected = false;
        }
      },
      err => {
        this.courseDetail.courseImages = [];
        SharedIonic.dismissLoading(this.loadingController);
        SharedIonic.unSuccessToast(this.toastController);
        this.selectedCourseId = 0;
        this.courseSelected = false;
      }
    );

    // if (model.isActive) {
    //   this.courseService.GetTeacherCourseById(+model.id).subscribe(

    //     res => {
    //       SharedIonic.dismissLoading(this.loadingController);
    //       if (GResponse.SuccessStatus === res.status) {
    //         this.courseDetail = res.data;
    //         this.updateForm.setValue({
    //           name: '',
    //           url: ''
    //         });
    //         this.courseSelected = true;
    //       } else {
    //         SharedIonic.unSuccessToast(this.toastController);
    //         this.selectedCourseId = 0;
    //         this.courseSelected = false;
    //       }
    //     },
    //     err => {
    //       SharedIonic.dismissLoading(this.loadingController);
    //       SharedIonic.unSuccessToast(this.toastController);
    //       this.selectedCourseId = 0;
    //       this.courseSelected = false;
    //     }
    //   );
    // } else {
    //   this.courseService.GetDeActiveCourseById(+model.id).subscribe(

    //     res => {
    //       SharedIonic.dismissLoading(this.loadingController);
    //       if (GResponse.SuccessStatus === res.status) {
    //         this.courseDetail = res.data;
    //         this.updateForm.setValue({
    //           name: '',
    //           url: ''
    //         });
    //         this.courseSelected = true;
    //       } else {
    //         SharedIonic.unSuccessToast(this.toastController);
    //         this.selectedCourseId = 0;
    //         this.courseSelected = false;
    //       }
    //     },
    //     err => {
    //       SharedIonic.dismissLoading(this.loadingController);
    //       SharedIonic.unSuccessToast(this.toastController);
    //       this.selectedCourseId = 0;
    //       this.courseSelected = false;
    //     }
    //   );
    // }
  }

  onCancel() {

    this.selectedCourseId = 0;
    this.courseSelected = false;
  }
}
